VARIANTS = ["baseline-v1", "without-doctoral-defense-v1"]


@dataclass(frozen=True)
class PromptExamplePair:
    """Một cặp ví dụ human/assistant bất biến."""

    pair_id: str
    human_content: str
    assistant_content: str


@dataclass(frozen=True)
class PromptExampleGroup:
    """Một nhóm ví dụ prompt có thứ tự."""

    group_id: str
    pairs: tuple[PromptExamplePair, ...]


@dataclass(frozen=True)
class PromptVariant:
    """Một composition treatment có thứ tự."""

    variant_id: str
    included_group_ids: tuple[str, ...]
    excluded_group_ids: tuple[str, ...]
    schema_version: int = 1


def prompt_registry() -> dict[str, Any]:
    """Trả bản sao sâu của registry bất biến do eval sở hữu."""
    return json.loads(json.dumps(REGISTRY, ensure_ascii=False))


def baseline_references() -> list[dict[str, Any]]:
    """Trả bản sao sâu của mười baseline request identity đóng băng."""
    return json.loads(json.dumps(BASELINE_REFERENCES, ensure_ascii=False))


def _groups() -> tuple[PromptExampleGroup, ...]:
    """Dựng group có kiểu từ registry đóng băng."""
    return tuple(
        PromptExampleGroup(
            group_id=group["group_id"],
            pairs=tuple(PromptExamplePair(**pair) for pair in group["pairs"]),
        )
        for group in REGISTRY["groups"]
    )


def variants() -> tuple[PromptVariant, ...]:
    """Trả định nghĩa baseline và ablated treatment theo thứ tự."""
    return tuple(PromptVariant(**variant) for variant in REGISTRY["variants"])


def messages_for_variant(variant_id: str) -> list[dict[str, str]]:
    """Trả literal message của ví dụ cho một treatment evaluation."""
    by_id = {group.group_id: group for group in _groups()}
    selected = next((variant for variant in variants() if variant.variant_id == variant_id), None)
    if selected is None:
        raise ValueError(f"unknown prompt variant: {variant_id!r}")
    messages: list[dict[str, str]] = []
    for group_id in selected.included_group_ids:
        for pair in by_id[group_id].pairs:
            messages.extend(
                [
                    {"role": "human", "content": pair.human_content},
                    {"role": "ai", "content": pair.assistant_content},
                ]
            )
    return messages


